optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/evidence_validation.rs b/tools/bot-evaluation/src/evidence_validation.rs
index 5dfa8765..cdf72c63 100644
--- a/tools/bot-evaluation/src/evidence_validation.rs
+++ b/tools/bot-evaluation/src/evidence_validation.rs
@@ -3,12 +3,11 @@
 //! content once, then validate its containing report with the same (empty)
 //! timeline type. Reads always validate the complete persisted XML document.
 use crate::{
-    identity,
     xml::{self, Result},
 };
 use quick_xml::{events::Event, Reader};
 use std::{cell::RefCell, collections::VecDeque};
-thread_local! {static VALIDATED:RefCell<VecDeque<String>>=const {RefCell::new(VecDeque::new())};}
+thread_local! {static VALIDATED:RefCell<VecDeque<[u8; 32]>>=const {RefCell::new(VecDeque::new())};}
 const PREFIX: &[u8] = br#"<timeline-fragment schema_version="1" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">"#;
 const SUFFIX: &[u8] = b"</timeline-fragment>";
 pub fn prepare() -> Result<()> {
@@ -56,7 +55,7 @@ fn validate_timeline(bytes: &[u8]) -> Result<()> {
     xml::validate("timeline-fragment", &fragment)
 }
 fn timeline(bytes: &[u8]) -> Result<()> {
-    let hash = identity::sha(bytes);
+    let hash: [u8; 32] = { use sha2::{Digest, Sha256}; Sha256::digest(bytes).into() };
     if VALIDATED.with(|cache| cache.borrow().contains(&hash)) {
         return Ok(());
     }
